// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {Base64} from "@openzeppelin/contracts/utils/Base64.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";

interface IAgentIdRegistry {
    function handleOf(address wallet) external view returns (string memory);
}

/// @title Agentic Pixels - 2,000 fully onchain pixel characters for AI agents with an Agent ID on BNB Chain.
/// @notice Unofficial community project, not affiliated with Binance.
/// Agent ID holders only. 200 Epic, 300 Rare, 1,500 Common, revealed instantly. 1st mint free, 2nd and 3rd paid, max 3 per wallet and per Agent ID; payments forwarded instantly. No owner, no admin, no upgrades, no withdraw.
contract AgenticPixels is ERC721 {
    using Strings for uint256;

    uint256 public constant MAX_SUPPLY = 2000;
    /// @notice Binance Agent ID registry on BNB Smart Chain, hardcoded.
    IAgentIdRegistry public constant registry = IAgentIdRegistry(0x60B9262456dE011F7d15a54CdD8c48bAaa8B022F);
    uint256 public immutable mintStart;
    uint256 public constant MAX_PER_WALLET = 3;
    uint256 public immutable PRICE;  // price of the 2nd mint (1st is free)
    uint256 public immutable PRICE3; // price of the 3rd mint
    address payable public immutable payTo; // mint payments go here instantly; contract holds no funds

    uint256 public totalMinted;
    mapping(address => uint256) public mintedBy;
    mapping(bytes32 => uint256) public mintedByAgentId;
    mapping(uint256 => uint256) public seedOf;

    // exact rarity pool, drawn without replacement at mint (instant reveal)
    uint256 public constant RARE_SUPPLY = 300;
    uint256 public constant EPIC_SUPPLY = 200;
    uint256 private constant CREATOR_EPICS = 5; // reserved for the creator at deploy, disclosed on the site
    // packed in one slot so every mint costs the same gas whatever rarity it draws
    uint64 public rareLeft = uint64(RARE_SUPPLY);
    uint64 public epicLeft = uint64(EPIC_SUPPLY);
    uint64 public commonLeft = uint64(MAX_SUPPLY - RARE_SUPPLY - EPIC_SUPPLY);

    event Minted(address indexed to, uint256 indexed tokenId, uint8 rarity, string agentId);

    constructor(uint256 mintStart_, uint256 price_, uint256 price3_, address payable payTo_) ERC721("Agentic Pixels", "AGPX") {
        mintStart = mintStart_;
        PRICE = price_;
        PRICE3 = price3_;
        payTo = payTo_;
        // Creator reserve, public and onchain: tokens #1-#5 are Epic and go to the creator at deploy.
        // They come out of the 200 Epic, so 195 Epic remain for the public draw.
        epicLeft -= uint64(CREATOR_EPICS);
        for (uint256 i; i < CREATOR_EPICS; i++) {
            uint256 id = ++totalMinted;
            uint256 seed = uint256(keccak256(abi.encodePacked(block.prevrandao, payTo_, id)));
            seedOf[id] = (seed & ~uint256(0xff)) | 2;
            _mint(payTo_, id);
        }
    }

    /// @notice The AI check. Every wallet gets its own two numbers.
    function challengeOf(address wallet) public view returns (string memory question, uint256 a, uint256 b) {
        uint256 h = uint256(keccak256(abi.encodePacked("Agentic Pixels", wallet)));
        a = h % 90 + 10;
        b = (h >> 8) % 90 + 10;
        question = string(abi.encodePacked("What is ", a.toString(), " x ", b.toString(), " plus the number of characters in your Agent ID (without .ai)?"));
    }

    function _answerOf(address wallet, string memory handle) private view returns (uint256) {
        (, uint256 a, uint256 b) = challengeOf(wallet);
        return a * b + bytes(handle).length;
    }

    /// @dev nth mint (1-based) costs: 1st free, 2nd PRICE, 3rd PRICE3
    function _cost(uint256 used, uint256 qty) private view returns (uint256 c) {
        for (uint256 n = used + 1; n <= used + qty && n <= MAX_PER_WALLET; n++) {
            if (n == 2) c += PRICE; else if (n == 3) c += PRICE3;
        }
    }

    /// @notice cost for `wallet` to mint `qty` more, and how many it can still mint.
    function quote(address wallet, uint256 qty) public view returns (uint256 cost, uint256 remaining) {
        uint256 used = mintedBy[wallet];
        string memory handle = registry.handleOf(wallet);
        if (bytes(handle).length > 0) {
            uint256 a = mintedByAgentId[keccak256(bytes(handle))];
            if (a > used) used = a;
        }
        remaining = used >= MAX_PER_WALLET ? 0 : MAX_PER_WALLET - used;
        cost = _cost(used, qty);
    }

    function mintOpen() public view returns (bool) {
        return block.timestamp >= mintStart && totalMinted < MAX_SUPPLY;
    }

    function agentIdOf(address wallet) public view returns (string memory) {
        return registry.handleOf(wallet);
    }

    function mint(uint256 qty, uint256 answer) external payable {
        require(qty > 0, "qty 0");
        require(msg.sender == tx.origin, "EOA only");
        require(block.timestamp >= mintStart, "Not started");
        require(totalMinted + qty <= MAX_SUPPLY, "Sold out");
        string memory handle = registry.handleOf(msg.sender);
        require(bytes(handle).length > 0, "Agent ID required");
        require(answer == _answerOf(msg.sender, handle), "Wrong answer");
        bytes32 h = keccak256(bytes(handle));
        uint256 w = mintedBy[msg.sender];
        uint256 a = mintedByAgentId[h];
        require(w + qty <= MAX_PER_WALLET, "Wallet limit");
        require(a + qty <= MAX_PER_WALLET, "Agent ID limit");
        uint256 used = w > a ? w : a;
        require(msg.value == _cost(used, qty), "Wrong BNB amount");

        mintedBy[msg.sender] = w + qty;
        mintedByAgentId[h] = a + qty;
        for (uint256 i; i < qty; i++) {
            uint256 id = ++totalMinted;
            uint256 seed = uint256(keccak256(abi.encodePacked(block.prevrandao, blockhash(block.number - 1), msg.sender, id)));
            uint8 rar = _drawRarity(seed);
            // rarity lives in the low byte of the seed: one storage write, same gas for every rarity
            seedOf[id] = (seed & ~uint256(0xff)) | rar;
            _mint(msg.sender, id);
            emit Minted(msg.sender, id, rar, handle);
        }
        if (msg.value > 0) {
            (bool ok, ) = payTo.call{value: msg.value}("");
            require(ok, "Pay failed");
        }
    }

    function _drawRarity(uint256 seed) private returns (uint8 rar) {
        uint64 r_ = rareLeft; uint64 e_ = epicLeft; uint64 c_ = commonLeft;
        uint256 x = (seed >> 128) % (uint256(r_) + e_ + c_);
        uint256 isEpic = x < e_ ? 1 : 0;
        uint256 isRare = (x >= e_ && x < uint256(e_) + r_) ? 1 : 0;
        uint256 isCommon = 1 - isEpic - isRare;
        (rareLeft, epicLeft, commonLeft) = (r_ - uint64(isRare), e_ - uint64(isEpic), c_ - uint64(isCommon));
        rar = uint8(isEpic * 2 + isRare);
    }

    // ---------------- traits ----------------

    function _bg(uint256 i) private pure returns (string memory) { string[8] memory a = ["#1E2026","#2B2F36","#0B3D2E","#0E4F5C","#123A6B","#5C1F2B","#F5F5F5","#FFE8A3"]; return a[i]; }
    function _bg_n(uint256 i) private pure returns (string memory) { string[8] memory a = ["Night","Graphite","Forest","Teal","Ocean","Wine","Cloud","Cream"]; return a[i]; }
    function _body(uint256 i) private pure returns (string memory) { string[6] memory a = ["#F0B90B","#F8D12F","#E8A33D","#7FD6A4","#8FB8FF","#FF9AC1"]; return a[i]; }
    function _body_n(uint256 i) private pure returns (string memory) { string[6] memory a = ["BNB Gold","Lemon","Honey","Mint","Sky","Bubblegum"]; return a[i]; }
    function _eyes_n(uint256 i) private pure returns (string memory) { string[5] memory a = ["Dots","Big","Sleepy","Laser","Shades"]; return a[i]; }
    function _mouth_n(uint256 i) private pure returns (string memory) { string[5] memory a = ["Smile","Wow","Flat","Tongue","Grin"]; return a[i]; }
    function _hat_n(uint256 i) private pure returns (string memory) { string[6] memory a = ["None","Cap","Crown","Beanie","Halo","Diamond"]; return a[i]; }
    function _acc_n(uint256 i) private pure returns (string memory) { string[5] memory a = ["None","Gold Chain","Blush","Bow Tie","Sweat"]; return a[i]; }

    /// @notice Display-only creator address so marketplaces (Element, OpenSea) let the creator edit
    /// the collection profile. It has NO powers in this contract: nothing is onlyOwner.
    function owner() external view returns (address) { return payTo; }

    /// @notice 0 Common, 1 Rare, 2 Epic
    function rarityOf(uint256 id) public view returns (uint8) {
        _requireOwned(id);
        return uint8(seedOf[id] & 0xff);
    }

    function traitsOf(uint256 id) public view returns (uint8 bg, uint8 body, uint8 eyes, uint8 mouth, uint8 hat, uint8 acc) {
        _requireOwned(id);
        uint256 s = seedOf[id] >> 8;
        bg = uint8(s % 8); s >>= 8;
        body = uint8(s % 6); s >>= 8;
        eyes = uint8(s % 5); s >>= 8;
        mouth = uint8(s % 5); s >>= 8;
        hat = uint8(s % 6); s >>= 8;
        acc = uint8(s % 5);
    }

    function _r(uint256 x, uint256 y, uint256 w, uint256 h, string memory c) private pure returns (bytes memory) {
        return abi.encodePacked('<rect x="', x.toString(), '" y="', y.toString(), '" width="', w.toString(), '" height="', h.toString(), '" fill="', c, '"/>');
    }

    function _eyes(uint8 t) private pure returns (bytes memory) {
        if (t == 0) return abi.encodePacked(_r(5,8,1,2,"#111"), _r(10,8,1,2,"#111"));
        if (t == 1) return abi.encodePacked(_r(4,7,3,3,"#FFF"), _r(9,7,3,3,"#FFF"), _r(5,8,1,1,"#111"), _r(10,8,1,1,"#111"));
        if (t == 2) return abi.encodePacked(_r(4,9,3,1,"#111"), _r(9,9,3,1,"#111"));
        if (t == 3) return abi.encodePacked(_r(4,8,3,1,"#FF2D2D"), _r(9,8,3,1,"#FF2D2D"), _r(12,8,4,1,"#FF6B6B"));
        return abi.encodePacked(_r(3,8,10,1,"#111"), _r(4,9,3,1,"#111"), _r(9,9,3,1,"#111"));
    }

    function _mouth(uint8 t) private pure returns (bytes memory) {
        if (t == 0) return abi.encodePacked(_r(6,12,4,1,"#111"), _r(5,11,1,1,"#111"), _r(10,11,1,1,"#111"));
        if (t == 1) return _r(7,11,2,2,"#111");
        if (t == 2) return _r(6,12,4,1,"#111");
        if (t == 3) return abi.encodePacked(_r(6,11,4,1,"#111"), _r(7,12,2,1,"#FF5A7A"));
        return abi.encodePacked(_r(5,11,6,2,"#111"), _r(6,11,4,1,"#FFF"));
    }

    function _hat(uint8 t) private pure returns (bytes memory) {
        if (t == 1) return abi.encodePacked(_r(4,2,8,2,"#E8453C"), _r(10,3,4,1,"#E8453C"));
        if (t == 2) return abi.encodePacked(_r(4,2,8,2,"#FFD700"), _r(4,1,1,1,"#FFD700"), _r(7,0,2,2,"#FFD700"), _r(11,1,1,1,"#FFD700"), _r(7,2,2,1,"#E8453C"));
        if (t == 3) return abi.encodePacked(_r(4,1,8,3,"#3D6BE8"), _r(4,3,8,1,"#2A4FB8"), _r(7,0,2,1,"#FFF"));
        if (t == 4) return abi.encodePacked(_r(5,0,6,1,"#FFE35A"), _r(4,1,1,1,"#FFE35A"), _r(11,1,1,1,"#FFE35A"));
        if (t == 5) return abi.encodePacked(_r(7,0,2,1,"#F0B90B"), _r(6,1,4,1,"#F0B90B"), _r(7,2,2,1,"#F0B90B"));
        return "";
    }

    function _acc(uint8 t) private pure returns (bytes memory) {
        if (t == 1) return abi.encodePacked(_r(5,14,6,1,"#FFD700"), _r(7,15,2,1,"#FFD700"));
        if (t == 2) return abi.encodePacked(_r(3,11,2,1,"#FF8FA8"), _r(11,11,2,1,"#FF8FA8"));
        if (t == 3) return abi.encodePacked(_r(6,14,1,2,"#E8453C"), _r(7,14,2,1,"#E8453C"), _r(9,14,1,2,"#E8453C"));
        if (t == 4) return abi.encodePacked(_r(13,5,1,1,"#9AD8FF"), _r(12,6,2,2,"#9AD8FF"));
        return "";
    }

    function _frame(uint8 r) private pure returns (bytes memory) {
        if (r == 0) return "";
        string memory c = r == 2 ? "#F0B90B" : "#C9D1DB";
        bytes memory f = abi.encodePacked('<path d="M0 0h16v16H0z M0.5 0.5v15h15v-15z" fill="', c, '" fill-rule="evenodd"/>');
        if (r == 2) f = abi.encodePacked(f, _r(1,1,1,1,"#FFF6C2"), _r(14,1,1,1,"#FFF6C2"), _r(1,14,1,1,"#FFF6C2"), _r(14,14,1,1,"#FFF6C2"));
        return f;
    }

    function svgOf(uint256 id) public view returns (string memory) {
        (uint8 bg, uint8 body, uint8 eyes, uint8 mouth, uint8 hat, uint8 acc) = traitsOf(id);
        string memory b = _body(body);
        bytes memory bodyArt = abi.encodePacked(_r(4,4,8,1,b), _r(3,5,10,9,b), _r(4,14,8,2,b), _r(2,9,1,3,b), _r(13,9,1,3,b));
        return string(abi.encodePacked(
            '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" shape-rendering="crispEdges" width="480" height="480">',
            _r(0,0,16,16,_bg(bg)), bodyArt, _eyes(eyes), _mouth(mouth), _hat(hat), _acc(acc), _frame(rarityOf(id)), '</svg>'));
    }

    function _attr(string memory k, string memory v) private pure returns (bytes memory) {
        return abi.encodePacked('{"trait_type":"', k, '","value":"', v, '"}');
    }

    function tokenURI(uint256 id) public view override returns (string memory) {
        (uint8 bg, uint8 body, uint8 eyes, uint8 mouth, uint8 hat, uint8 acc) = traitsOf(id);
        bytes memory attrs = abi.encodePacked(
            _attr("Rarity", ["Common","Rare","Epic"][rarityOf(id)]), ",", _attr("Background", _bg_n(bg)), ",", _attr("Body", _body_n(body)), ",", _attr("Eyes", _eyes_n(eyes)), ",",
            _attr("Mouth", _mouth_n(mouth)), ",", _attr("Hat", _hat_n(hat)), ",", _attr("Accessory", _acc_n(acc)));
        bytes memory json = abi.encodePacked(
            '{"name":"Agentic Pixel #', id.toString(),
            '","description":"Agentic Pixels: 2,000 fully onchain pixel characters minted by AI agents holding an Agent ID on BNB Chain. Independent community project, not affiliated with Binance.","image":"data:image/svg+xml;base64,',
            Base64.encode(bytes(svgOf(id))), '","attributes":[', attrs, ']}');
        return string(abi.encodePacked("data:application/json;base64,", Base64.encode(json)));
    }

    // ERC-2981: 2% royalty to the creator on outside marketplaces that honor it
    function royaltyInfo(uint256, uint256 salePrice) external view returns (address, uint256) {
        return (payTo, salePrice * 200 / 10000);
    }

    function supportsInterface(bytes4 interfaceId) public view override returns (bool) {
        return interfaceId == 0x2a55205a || super.supportsInterface(interfaceId);
    }

    function tokensOf(address owner) external view returns (uint256[] memory ids) {
        uint256 n = balanceOf(owner);
        ids = new uint256[](n);
        uint256 k;
        for (uint256 i = 1; i <= totalMinted && k < n; i++) {
            if (_ownerOf(i) == owner) ids[k++] = i;
        }
    }
}
